fn animation_clip_choices_cached(
    cache: &mut Option<AnimationClipChoicesCache>,
    scene: &AuthoringScene,
    entity: &EntityId,
    manifest: &engine::AssetManifest,
    assets_root: Option<&Path>,
) -> Arc<Vec<AnimationClipChoice>> {
    let Some(Value::Object(fields)) = animation_controller_value(scene, entity) else {
        return Arc::new(Vec::new());
    };
    // The controller names its clips through the assigned Animation Set only.
    let (Some(Value::AssetRef(animation_set)), Some(assets_root)) =
        (fields.get("animation_set"), assets_root)
    else {
        return Arc::new(Vec::new());
    };
    let Some(entry) = manifest.get(animation_set) else {
        return Arc::new(Vec::new());
    };
    let path = assets_root.join(&entry.path);
    let Ok(stamp) = engine::SourceStamp::capture(&path, &[]) else {
        return Arc::new(Vec::new());
    };
    if let Some(cached) = cache.as_ref()
        && cached.animation_set == *animation_set
        && cached.path == path
        && cached.stamp == stamp
    {
        return Arc::clone(&cached.choices);
    }

    let choices = std::fs::read_to_string(&path)
        .ok()
        .and_then(|json| engine_authoring::AnimationSet::from_json(&json).ok())
        .map(|set| animation_set_clip_choices(&set))
        .unwrap_or_default();
    let choices = Arc::new(choices);
    *cache = Some(AnimationClipChoicesCache {
        animation_set: animation_set.clone(),
        path,
        stamp,
        choices: Arc::clone(&choices),
    });
    choices
}
